using System;using System.Drawing;using System.Windows.Forms;class FocusTest{static int Count(Bitmap b,int x,int y,int w,int h){int c=0;for(int i=x;i<x+w;i++)for(int j=y;j<y+h;j++)if(b.GetPixel(i,j).ToArgb()!=Color.White.ToArgb())c++;return c;}[STAThread]static void Main(){using(var form=new Atlas())using(var chart=new Chart())using(var bmp=new Bitmap(720,200)){chart.Size=bmp.Size;var data=new Inventory();foreach(var name in new[]{"Router","450E","Mini"})data.Devices.Add(new Device(name){Linked=true});var n=data.Devices;for(int i=0;i<2;i++)data.Links.Add(new Link(){A=n[i],B=n[i+1],Type=i==0?"LAN":"WLAN",Rx=28});chart.SetData(data);for(int i=0;i<3;i++)n[i].Pos=new PointF(80+220*i,80);foreach(var sel in new[]{-1,2,1,0,-1}){chart.SelectDevice(sel<0?null:n[sel]);chart.DrawToBitmap(bmp,chart.ClientRectangle);for(int i=0;i<3;i++){bool named=sel>=0&&Math.Abs(i-sel)<=1;if((Count(bmp,80+i*220-30,102,60,18)>0)!=named||Count(bmp,80+i*220-10,70,20,20)==0)throw new Exception("Symbol/Name");}for(int i=0;i<2;i++)if((Count(bmp,115+i*220,77,38,7)>0)!=(sel==i||sel==i+1))throw new Exception("Linie");}Console.WriteLine("OK");}}}